 }
 addedSources+=sources.length;addedTips+=newTips.length;
}
assert.deepEqual(changed.toSorted(),all.toSorted());
console.log("'`Audit passed: ${changed.length} cards, ${addedTips} added tips, ${addedSources} archived source objects, ${pinnedFields} changed fields pinned. All existing tips, sources, decisions, picks and other fields preserved except three question pronouns.`);
